static void testSequenceTools(const File& root,Assets& assets){
    auto source=emptyProject();source.bpm=120;source.loop=false;source.patterns[0].length=4;source.patterns[0].name="First";source.patterns[0].lanes[7]={{0,1,60,.8f},{3,2,64,.6f,.7f,2}};
    Pattern second;second.name="Second";second.length=3;second.lanes.resize(source.tracks.size());second.lanes[0]={{1,.25,36,.7f}};second.lanes[7]={{.5,.75,67,.4f,.3f,3}};source.patterns.push_back(second);source.clips={{7,0,0,4},{7,1,4,3}};source.songMode=true;
    Project output;PatternEditStats stats;expect(mergePatternSequence(source,0,1,output,&stats).wasOk()&&output.patterns.size()==3&&output.activePattern==2&&output.patterns[2].length==7&&stats.created==std::vector<int>{2},"sequential merge appends a new pattern using the sum of both source lengths");
    const auto& joined=output.patterns[2];auto shifted=second.lanes[7][0];shifted.beat+=4;expect(joined.lanes[7].front()==source.patterns[0].lanes[7].front()&&joined.lanes[7].back()==shifted&&joined.lanes[0][0].beat==5,"sequential merge retains articulation and shifts each second-pattern lane by the complete first length");expect(joined.lanes[7][1].length==2&&joined.lanes[7][1].beat==3,"sequential merge retains intentional gate overlap across the phrase boundary");
    expect(output.patterns[0].editorId==source.patterns[0].editorId&&joined.editorId!=source.patterns[0].editorId&&joined.editorId!=second.editorId&&JSON::toString(projectToJson(output)["clips"])==JSON::toString(projectToJson(source)["clips"]),"sequential merge assigns an independent identity and leaves source patterns and Playlist clips intact");
    auto manual=source;manual.songMode=false;for(size_t track=0;track<manual.tracks.size();++track)for(auto note:second.lanes[track]){note.beat+=4;manual.patterns[0].lanes[track].push_back(note);}manual.patterns[0].length=7;output.songMode=false;auto a=render(manual,assets,root,170000,127),b=render(output,assets,root,170000,511);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<170000;++i)difference=jmax(difference,std::abs(a.getSample(ch,i)-b.getSample(ch,i)));expect(difference<.000001f,"sequential merge audio matches a manually sequenced reference across callback sizes");
    auto sentinel=JSON::toString(projectToJson(output));stats={{17},19,21,22,23};auto tooLong=source;tooLong.patterns[0].length=62;expect(mergePatternSequence(tooLong,0,1,output,&stats).failed()&&JSON::toString(projectToJson(output))==sentinel&&stats.created==std::vector<int>{17},"overlong sequential merges preserve output and stats atomically");
    auto boundary=source;boundary.patterns[0].length=61;expect(mergePatternSequence(boundary,0,1,output).wasOk()&&output.patterns.back().length==64,"sequential merge supports exactly 64 beats");auto full=source;while(full.patterns.size()<maxPatterns)full.patterns.push_back(second);expect(mergePatternSequence(full,0,1,output).failed(),"sequential merge refuses a full pattern bank");
    auto dense=source;dense.patterns[0].lanes[7].assign(256,Note{0,.25,60,.8f});dense.patterns[1].lanes[7].assign(256,Note{0,.25,64,.8f});expect(mergePatternSequence(dense,0,1,output).wasOk()&&output.patterns.back().lanes[7].size()==512,"sequential merge accepts the exact per-lane note capacity");dense.patterns[1].lanes[7].push_back({1,.25,67,.8f});expect(mergePatternSequence(dense,0,1,output).failed(),"sequential merge rejects overflowing lanes without trimming notes");expect(mergePatternSequence(source,0,0,output).failed()&&mergePatternSequence(source,0,99,output).failed(),"self and stale sequential merge targets are rejected");
    auto backwards=source;expect(mergePatternSequence(backwards,1,0,backwards).wasOk()&&backwards.patterns.back().lanes[7].back().beat==6,"sequential merge preserves requested order and supports in-place source/output aliases");
    auto deleting=source;Pattern third;third.name="Third";third.lanes.resize(deleting.tracks.size());deleting.patterns.push_back(third);deleting.activePattern=1;Clip audio;audio.track=2;audio.audioPath="retained.wav";audio.pattern=99;audio.sourceOffset=.25;audio.length=2;Clip automation;automation.track=3;automation.automationTarget=5;automation.automationTrack=-1;automation.length=2;automation.points={{0,.8f,false},{2,.4f,true}};deleting.clips={{7,1,0,3},audio,{7,2,4,2},automation,{0,1,6,3},{7,0,9,4}};
    auto original=JSON::toString(projectToJson(deleting));expect(deletePatternWithClips(deleting,1,output,&stats).wasOk()&&output.patterns.size()==2&&output.clips.size()==4&&stats.removedClips==std::vector<int>{0,4}&&stats.removed==1,"used-pattern deletion removes exactly the referenced pattern clips and reports their original indices");expect(output.clips[0].audioPath=="retained.wav"&&output.clips[0].pattern==99&&output.clips[0].sourceOffset==.25&&output.clips[2].isAutomation()&&output.clips[2].points[1].value==.4f&&output.clips[1].pattern==1&&output.clips[3].pattern==0,"used-pattern deletion preserves complete audio/automation data and compacts only genuine pattern links");expect(output.activePattern==1&&output.patterns[1].editorId==third.editorId&&JSON::toString(projectToJson(deleting))==original,"deletion chooses the successor and leaves the source immutable");
    auto copy=deleting;expect(deletePatternWithClips(copy,1,copy).wasOk()&&copy.clips.size()==4,"used-pattern deletion safely supports source/output aliasing");auto bad=deleting;bad.clips.back().pattern=55;sentinel=JSON::toString(projectToJson(output));expect(deletePatternWithClips(bad,1,output).failed()&&JSON::toString(projectToJson(output))==sentinel,"malformed unrelated links cancel used-pattern deletion atomically");expect(deletePatternWithClips(emptyProject(),0,output).failed()&&deletePatternWithClips(deleting,99,output).failed(),"used-pattern deletion rejects the final pattern and stale targets");
    auto persisted=source;deletePatternWithClips(persisted,1,persisted);Project restored;expect(projectFromJson(projectToJson(persisted),restored).wasOk()&&restored.patterns.size()==1&&restored.clips.size()==1,"used-pattern deletion persists through the unchanged project schema");
}
